public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check for null input
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    // Get the length of the string
    int strLen = str.length();

    // Check if the string is empty
    if (strLen == 0) {
        return lb;
    }

    // Get the character encoding for the string
    CharsetEncoder encoder = session.getCharsetEncoder();

    // Get the maximum buffer size for the string
    int maxBufferSize = encoder.maxBytesPerChar();

    // Check if the string is too long to fit in the buffer
    if (strLen > maxBufferSize) {
        throw new IllegalArgumentException("String is too long to fit in the buffer");
    }

    // Get the byte buffer for the string
    ByteBuffer buffer = lb.getByteBuffer();

    // Encode the string into the byte buffer
    encoder.encode(CharBuffer.wrap(str), buffer, true);

    // Return the linked buffer
    return lb;
}

